  const n = nums.length;
  let drops = 0;
  for (let i = 0; i < n; i++) {
    const next = nums[(i + 1) % n];
    if (nums[i] > next) {
      drops++;
    }
    if (drops > 1) {
      return false;
    }
  }
  return true;
}

