function check(nums) {
  const sorted = [...nums].sort((a, b) => a - b);
  const n = nums.length;
  for (let x = 0; x < n; x++) {
    let same = true;
    for (let i = 0; i < n; i++) if (nums[i] !== sorted[(i + x) % n]) same = false;
    if (same) return true;
  }
  return false;
}

