function generate(rand, size) {
  const n = size === 'large' ? 80 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 7);
  const top = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  const values = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  if (rand() < 0.3) return [values];
  values.sort((a, b) => a - b);
  const x = Math.floor(rand() * n);
  const nums = values.slice(x).concat(values.slice(0, x));
  // Sometimes nudge one value so the result is almost, but not quite, a rotated sorted array.
  if (rand() < 0.4) {
    const i = Math.floor(rand() * n);
    nums[i] = 1 + Math.floor(rand() * top);
  }
  return [nums];
}
